Method.Source:
    /// <summary>
    /// Retrieves the RecId for a given Itemcode.
    /// </summary>
    /// <param name = "_recId">
    ///  The RecId of the metTariffItemCodeBase table
    ///  </param>
    /// <param name = "_transDate">
    /// Date for which we need to find the record
    /// </param>
    /// <param name = "_forUpdate">
    /// A Boolean value that determines whether the RecId of orign should be selected for update; optional.
    /// </param>
    /// <returns>
    /// The RecId.
    /// </returns>
    static METTariffItemCode 
        findRecId(RecId    _recId,
                                TransDate _transDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),
                                boolean  _forUpdate  = false)
    {
        METTariffItemCode metTariffItemCode;

        if (_recId)
        {
            select firstonly validtimestate(_transDate) metTariffItemCode
                where metTariffItemCode.MetTariffItemCodeBase == _recId;

            metTariffItemCode.selectForUpdate(_forUpdate);
            
        }

        return metTariffItemCode;
    }

    /// <summary>
    ///
    /// </summary>
    /// <returns></returns>
    public boolean validateDelete()
    {
        boolean ret;
    
        ret = super();

        TransDate todayDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        if (this.ValidFrom <= todayDate && this.ValidTo >= todayDate)
        {
            ret = checkFailed("@MET:EffectiveRecordDeleteValidationMsg");
        }

        if (this.ValidTo == dateMax())
        {
            ret = checkFailed(strfmt("@MET:EffectiveNeverDeleteValidationMsg", fieldPName(METTariffItemCode, ValidTo)));
        }

        METTariffItemCode currentEffectiveRecord = METTariffItemCode::findRecId(this.METTariffItemCodeBase, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));

        if ((currentEffectiveRecord.ValidTo + 1 ) == this.ValidFrom)
        {
            ret = checkFailed("@MET:TariffItemCrossingOverValidationMsg");
        }
    
        return ret;
    }

    /// <summary>
    ///
    /// </summary>
    /// <param name = "_fieldIdToCheck"></param>
    /// <returns></returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();

        if (this.orig().ValidTo == dateMax() && 
            this.ValidTo != this.orig().ValidTo &&
            !METTariffItemCode::existNeverExpirationRecod(this.METTariffItemCodeBase, this.RecId))
        {
            ret = checkFailed("@MET:TariffItemCodeNeverExpirationRetainMsg");
        }

    
        return ret;
    }

    public static boolean existNeverExpirationRecod(RefRecId _tariffItemCodeBase, RefRecId _tariffItemCodeCurrent)
    {
        METTariffItemCode tariffItemCode;

        select firstonly tariffItemCode
            where   tariffItemCode.METTariffItemCodeBase == _tariffItemCodeBase
            &&      tariffItemCode.ValidTo               == dateMax()
            &&      tariffItemCode.RecId                 != _tariffItemCodeCurrent;

        return tariffItemCode.RecId != 0;
    }
